CREATE TABLE IF NOT EXISTS pve_regions (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, display_name VARCHAR(255) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'enabled', sort_order INT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS pve_nodes (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, region_id BIGINT NOT NULL, name VARCHAR(255) NOT NULL, host VARCHAR(255) NOT NULL, port INT NOT NULL DEFAULT 8006, cluster_name VARCHAR(255) NOT NULL DEFAULT '', api_user VARCHAR(255) NOT NULL, api_token_id VARCHAR(255) NOT NULL, api_token_secret TEXT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'enabled', last_checked_at BIGINT NULL, last_error TEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, KEY(region_id), CONSTRAINT pve_nodes_region_fk FOREIGN KEY(region_id) REFERENCES pve_regions(id));
CREATE TABLE IF NOT EXISTS pve_instance_flavors (instance_flavor_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, instance_flavor_code VARCHAR(64) NOT NULL, name VARCHAR(255) NOT NULL, cpu_cores INT NOT NULL, memory_gb INT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'enabled', sort_order INT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, UNIQUE KEY(cpu_cores, memory_gb));
CREATE TABLE IF NOT EXISTS pve_vms (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(16) NOT NULL DEFAULT 'qemu', region_id BIGINT NOT NULL, node_id BIGINT NOT NULL, instance_flavor_id BIGINT NOT NULL, name VARCHAR(255) NOT NULL DEFAULT '', status VARCHAR(16) NOT NULL DEFAULT 'allocating', pve_status VARCHAR(32) NOT NULL DEFAULT '', pve_config JSON NOT NULL, error_message TEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, deleted_at BIGINT NULL, KEY(region_id), KEY(node_id), CONSTRAINT pve_vms_region_fk FOREIGN KEY(region_id) REFERENCES pve_regions(id), CONSTRAINT pve_vms_node_fk FOREIGN KEY(node_id) REFERENCES pve_nodes(id), CONSTRAINT pve_vms_flavor_fk FOREIGN KEY(instance_flavor_id) REFERENCES pve_instance_flavors(instance_flavor_id));
CREATE TABLE IF NOT EXISTS pve_vm_tasks (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, vm_id BIGINT NOT NULL, action VARCHAR(32) NOT NULL, idempotency_key VARCHAR(255) NOT NULL UNIQUE, status VARCHAR(16) NOT NULL DEFAULT 'pending', request_payload JSON NOT NULL, response_payload JSON NOT NULL, retry_count INT NOT NULL DEFAULT 0, error_message TEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT pve_vm_tasks_vm_fk FOREIGN KEY(vm_id) REFERENCES pve_vms(id));
